	if g.token == "" {
		return nil
	}
	n, err := wordpress.FillWordPress(r, g.token, g.wpVulnCaches)
	if err != nil {
		return xerrors.Errorf("Failed to fetch from WPVulnDB. Check the WPVulnDBToken in config.toml. err: %w", err)
	}
	ints.WordPressCveCounts = n
	return nil
}

